{
    "sql": "WITH FemaleClientAccounts AS (SELECT c.client_id, c.birth_date, d.account_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE c.gender = 'F'), OldestFemaleAccounts AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), AccountAvgSalary AS (SELECT a.account_id, AVG(t.amount) AS avg_salary FROM account a JOIN trans t ON a.account_id = t.account_id WHERE t.type = 'credit' GROUP BY a.account_id), LowestAvgSalaryAccounts AS (SELECT account_id FROM AccountAvgSalary WHERE avg_salary = (SELECT MIN(avg_salary) FROM AccountAvgSalary)), TargetAccounts AS (SELECT o.account_id FROM OldestFemaleAccounts o INTERSECT SELECT l.account_id FROM LowestAvgSalaryAccounts l), SalaryGap AS (SELECT MAX(avg_salary) - MIN(avg_salary) AS salary_gap FROM AccountAvgSalary) SELECT t.account_id, s.salary_gap FROM TargetAccounts t CROSS JOIN SalaryGap s"
}

{
    "sql": "SELECT a.account_id, (MAX(d.A11) - MIN(d.A11)) AS salary_gap FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F' AND c.birth_date = (SELECT MIN(birth_date) FROM client WHERE gender = 'F') GROUP BY a.account_id HAVING AVG(d.A11) = (SELECT MIN(avg_salary) FROM (SELECT AVG(d2.A11) AS avg_salary FROM client c2 JOIN district d2 ON c2.district_id = d2.district_id WHERE c2.gender = 'F' GROUP BY c2.client_id) AS subquery)"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT DISTINCT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F'), OldestFemale AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), SalaryStats AS (SELECT MIN(avg_salary) AS min_avg_salary, MAX(avg_salary) AS max_avg_salary FROM FemaleClientAccounts WHERE account_id IN (SELECT account_id FROM OldestFemale)) SELECT account_id, (max_avg_salary - min_avg_salary) AS salary_gap FROM OldestFemale, SalaryStats"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT c.client_id, c.gender, c.birth_date, d.account_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE c.gender = 'F'), OldestFemaleAccounts AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), DistrictAvgSalary AS (SELECT district_id, A11 AS avg_salary FROM district), AccountAvgSalary AS (SELECT d.account_id, da.avg_salary FROM disp d JOIN DistrictAvgSalary da ON (SELECT district_id FROM account WHERE account_id = d.account_id) = da.district_id), OldestFemaleAvgSalary AS (SELECT o.account_id, a.avg_salary FROM OldestFemaleAccounts o JOIN AccountAvgSalary a ON o.account_id = a.account_id), LowestAvgSalary AS (SELECT account_id, avg_salary FROM OldestFemaleAvgSalary WHERE avg_salary = (SELECT MIN(avg_salary) FROM OldestFemaleAvgSalary)), HighestAvgSalary AS (SELECT MAX(avg_salary) AS max_avg_salary FROM DistrictAvgSalary) SELECT l.account_id, (h.max_avg_salary - l.avg_salary) AS salary_gap FROM LowestAvgSalary l CROSS JOIN HighestAvgSalary h"
}

{
