{
    "sql": "WITH first_loan_client AS (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' AND l.status = 'A' ORDER BY l.loan_id LIMIT 1), client_account AS (SELECT d.account_id FROM disp d JOIN first_loan_client flc ON d.account_id = flc.account_id WHERE d.type = 'OWNER' LIMIT 1), balance_start AS (SELECT t.account_id, t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date <= '1993-03-22' ORDER BY t.date DESC LIMIT 1), balance_end AS (SELECT t.account_id, t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date <= '1998-12-27' ORDER BY t.date DESC LIMIT 1) SELECT ROUND(((be.balance - bs.balance) * 100.0 / bs.balance), 2) AS increase_rate FROM balance_start bs JOIN balance_end be ON bs.account_id = be.account_id"
}

{
    "sql": "WITH first_loan_client AS (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' AND l.status = 'A' ORDER BY l.date LIMIT 1), client_account AS (SELECT d.account_id FROM disp d JOIN first_loan_client flc ON d.account_id = flc.account_id WHERE d.type = 'OWNER' LIMIT 1), balance_start AS (SELECT t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date = '1993-03-22' ORDER BY t.date DESC LIMIT 1), balance_end AS (SELECT t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date = '1998-12-27' ORDER BY t.date DESC LIMIT 1) SELECT CASE WHEN bs.balance = 0 THEN NULL ELSE ((be.balance - bs.balance) * 100.0 / bs.balance) END AS increase_rate FROM balance_start bs, balance_end be"
}

{
    "sql": "WITH first_loan_client AS (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' AND l.status = 'A' ORDER BY l.loan_id LIMIT 1), client_balance AS (SELECT t.account_id, t.balance FROM trans t WHERE t.account_id = (SELECT account_id FROM first_loan_client) AND t.date = '1993-03-22' ORDER BY t.trans_id DESC LIMIT 1), client_balance_later AS (SELECT t.account_id, t.balance FROM trans t WHERE t.account_id = (SELECT account_id FROM first_loan_client) AND t.date = '1998-12-27' ORDER BY t.trans_id DESC LIMIT 1) SELECT ((cbl.balance - cb.balance) * 100.0 / cb.balance) AS increase_rate FROM client_balance cb JOIN client_balance_later cbl ON cb.account_id = cbl.account_id"
}

{
    "sql": "WITH first_loan_client AS (SELECT l.account_id FROM loan l WHERE l.date = '1993-07-05' AND l.status = 'A' ORDER BY l.date LIMIT 1), client_account AS (SELECT d.account_id FROM disp d JOIN first_loan_client flc ON d.account_id = flc.account_id WHERE d.type = 'OWNER' LIMIT 1), balance_start AS (SELECT t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date = '1993-03-22' ORDER BY t.date DESC, t.trans_id DESC LIMIT 1), balance_end AS (SELECT t.balance FROM trans t JOIN client_account ca ON t.account_id = ca.account_id WHERE t.date = '1998-12-27' ORDER BY t.date DESC, t.trans_id DESC LIMIT 1) SELECT ROUND(((be.balance - bs.balance) * 100.0 / bs.balance), 2) AS increase_rate FROM balance_start bs, balance_end be WHERE bs.balance IS NOT NULL AND be.balance IS NOT NULL"
