{
    "sql": "SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)) AS percentage FROM (SELECT bond.bond_id, MIN(atom.element) AS element1, MAX(atom.element) AS element2 FROM bond JOIN connected ON bond.bond_id = connected.bond_id JOIN atom ON (connected.atom_id = atom.atom_id OR connected.atom_id2 = atom.atom_id) GROUP BY bond.bond_id HAVING COUNT(DISTINCT atom.element) = 2) AS bond_elements WHERE (element1, element2) = (SELECT element1, element2 FROM (SELECT MIN(atom.element) AS element1, MAX(atom.element) AS element2, COUNT(*) AS count FROM bond JOIN connected ON bond.bond_id = connected.bond_id JOIN atom ON (connected.atom_id = atom.atom_id OR connected.atom_id2 = atom.atom_id) GROUP BY bond.bond_id HAVING COUNT(DISTINCT atom.element) = 2 GROUP BY MIN(atom.element), MAX(atom.element) ORDER BY count DESC LIMIT 1))"
}

{
    "sql": "SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)) AS percentage FROM (SELECT bond_id, COUNT(*) AS count FROM (SELECT c.bond_id, a1.element AS element1, a2.element AS element2 FROM connected c JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id) GROUP BY bond_id, element1, element2) WHERE count = (SELECT MAX(count) FROM (SELECT COUNT(*) AS count FROM (SELECT c.bond_id, a1.element AS element1, a2.element AS element2 FROM connected c JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id) GROUP BY bond_id, element1, element2))"
}

{
    "sql": "SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)) AS percentage FROM (SELECT a1.element || '-' || a2.element AS element_pair, COUNT(*) AS pair_count FROM connected c JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id JOIN bond b ON c.bond_id = b.bond_id GROUP BY a1.element, a2.element ORDER BY pair_count DESC LIMIT 1)"
}

{
    "sql": "SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)) AS percentage FROM (SELECT bond.bond_id FROM bond JOIN connected ON bond.bond_id = connected.bond_id JOIN atom a1 ON connected.atom_id = a1.atom_id JOIN atom a2 ON connected.atom_id2 = a2.atom_id GROUP BY bond.bond_id, a1.element, a2.element ORDER BY COUNT(*) DESC LIMIT 1) AS most_common"
}

{
    "sql": "SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM bond)) AS percentage FROM (SELECT bond.bond_id FROM bond JOIN connected ON bond.bond_id = connected.bond_id JOIN atom a1 ON connected.atom_id = a1.atom_id JOIN atom a2 ON connected.atom_id2 = a2.atom_id GROUP BY bond.bond_id, a1.element, a2.element HAVING COUNT(*) = (SELECT MAX(cnt) FROM (SELECT COUNT(*) AS cnt FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id GROUP BY b.bond_id, a1.element, a2.element) sub)) sub2"
