    "sql": "SELECT AVG(set_count) AS annual_average_sets, fd.language AS common_language FROM (SELECT strftime('%Y', releaseDate) AS year, COUNT(*) AS set_count FROM sets WHERE releaseDate BETWEEN '2012-01-01' AND '2015-12-31' GROUP BY strftime('%Y', releaseDate)) AS yearly_counts CROSS JOIN (SELECT language, COUNT(*) AS lang_count FROM foreign_data GROUP BY language ORDER BY lang_count DESC LIMIT 1) AS fd"
