}

{
    "sql": "SELECT ((r1.fastestLapSpeed - r2.fastestLapSpeed) / r2.fastestLapSpeed * 100) AS percent_faster FROM results r1 JOIN results r2 ON r1.driverId = r2.driverId JOIN drivers d ON r1.driverId = d.driverId WHERE d.forename = 'Paul' AND d.surname = 'di Resta' AND r1.raceId = 853 AND r2.raceId = (SELECT MIN(raceId) FROM results WHERE driverId = r1.driverId AND raceId > 853)"
}

{
    "sql": "WITH race_853 AS (SELECT r1.raceId, r1.year, r1.round, r1.circuitId, r1.name, r1.date FROM races r1 WHERE r1.raceId = 853), next_race AS (SELECT r2.raceId, r2.year, r2.round, r2.circuitId, r2.name, r2.date FROM races r2 WHERE r2.year = (SELECT year FROM race_853) AND r2.round = (SELECT round FROM race_853) + 1), fastest_lap_speeds AS (SELECT res.raceId, res.driverId, res.fastestLapSpeed FROM results res WHERE res.driverId = (SELECT driverId FROM drivers WHERE forename = 'Paul' AND surname = 'di Resta') AND res.raceId IN (853, (SELECT raceId FROM next_race))) SELECT ((CAST(f1.fastestLapSpeed AS REAL) - CAST(f2.fastestLapSpeed AS REAL)) / CAST(f2.fastestLapSpeed AS REAL)) * 100.0 AS percent_faster FROM fastest_lap_speeds f1 JOIN fastest_lap_speeds f2 ON f1.raceId = 853 AND f2.raceId = (SELECT raceId FROM next_race);"
}

