    "sql": "SELECT ((r1.fastestLapSpeed - r2.fastestLapSpeed) / r2.fastestLapSpeed * 100) AS percent_faster FROM results r1 JOIN results r2 ON r1.driverId = r2.driverId JOIN drivers d ON r1.driverId = d.driverId JOIN races ra1 ON r1.raceId = ra1.raceId JOIN races ra2 ON r2.raceId = ra2.raceId WHERE d.forename = 'Paul' AND d.surname = 'di Resta' AND ra1.round = 853 AND ra2.round = 854 AND r1.fastestLapSpeed IS NOT NULL AND r2.fastestLapSpeed IS NOT NULL ORDER BY ra1.year, ra2.year LIMIT 1"
}

