}

{
    "sql": "SELECT d.driverId, d.forename, d.surname, COUNT(r.resultId) AS total_races, SUM(CASE WHEN r.statusId = (SELECT statusId FROM status WHERE status = 'Finished') THEN 1 ELSE 0 END) AS finished_races, CASE WHEN COUNT(r.resultId) > 0 THEN CAST(SUM(CASE WHEN r.statusId = (SELECT statusId FROM status WHERE status = 'Finished') THEN 1 ELSE 0 END) AS REAL) / COUNT(r.resultId) ELSE 0 END AS completion_rate FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '1983-07-16' GROUP BY d.driverId, d.forename, d.surname ORDER BY d.driverId"
}

{
    "sql": "SELECT d.driverId, d.forename, d.surname, COUNT(r.resultId) AS total_races, SUM(CASE WHEN r.statusId IN (SELECT statusId FROM status WHERE status LIKE '%Finished%' OR status LIKE '%Lap%') THEN 1 ELSE 0 END) AS completed_races, ROUND(CAST(SUM(CASE WHEN r.statusId IN (SELECT statusId FROM status WHERE status LIKE '%Finished%' OR status LIKE '%Lap%') THEN 1 ELSE 0 END) AS REAL) / COUNT(r.resultId) * 100, 2) AS completion_rate FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '1983-07-16' GROUP BY d.driverId, d.forename, d.surname ORDER BY completion_rate DESC"
}

{
    "sql": "SELECT d.driverId, d.forename, d.surname, COUNT(r.resultId) AS total_races, SUM(CASE WHEN r.position IS NOT NULL AND r.position > 0 THEN 1 ELSE 0 END) AS completed_races, ROUND(CAST(SUM(CASE WHEN r.position IS NOT NULL AND r.position > 0 THEN 1 ELSE 0 END) AS REAL) / COUNT(r.resultId) * 100, 2) AS completion_rate FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '1983-07-16' GROUP BY d.driverId, d.forename, d.surname ORDER BY completion_rate DESC"
}

{
    "sql": "SELECT d.driverId, d.forename, d.surname, COUNT(r.resultId) AS total_races, COUNT(CASE WHEN r.position IS NOT NULL AND r.position > 0 THEN 1 END) AS completed_races, ROUND(CAST(COUNT(CASE WHEN r.position IS NOT NULL AND r.position > 0 THEN 1 END) AS REAL) / COUNT(r.resultId) * 100, 2) AS completion_rate FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '1983-07-16' GROUP BY d.driverId, d.forename, d.surname"
}

