{
    "sql": "SELECT CASE WHEN Admission = 'in-patient' THEN 'in-patient' WHEN Admission = 'outpatient' THEN 'outpatient' ELSE 'Other' END AS admission_type, COUNT(*) AS count, (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM Patient WHERE SEX = 'male')) AS percentage FROM Patient WHERE SEX = 'male' AND Admission IN ('in-patient', 'outpatient') GROUP BY Admission ORDER BY count DESC"
}

{
    "sql": "SELECT CASE WHEN in_patient_count > out_patient_count THEN 'In-patient' ELSE 'Outpatient' END AS majority_group, ROUND(ABS(in_patient_count - out_patient_count) * 100.0 / (in_patient_count + out_patient_count), 2) AS percentage_deviation FROM (SELECT SUM(CASE WHEN p.Admission = 'In-patient' THEN 1 ELSE 0 END) AS in_patient_count, SUM(CASE WHEN p.Admission = 'Outpatient' THEN 1 ELSE 0 END) AS out_patient_count FROM Patient p WHERE p.SEX = 'Male') AS counts"
}

