    "sql": "SELECT CASE WHEN Admission = 'in-patient' THEN 'in-patient' ELSE 'outpatient' END AS patient_type, COUNT(*) AS count, (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM Patient WHERE SEX = 'male')) AS percentage FROM Patient WHERE SEX = 'male' GROUP BY CASE WHEN Admission = 'in-patient' THEN 'in-patient' ELSE 'outpatient' END"
}

{
    "sql": "SELECT CASE WHEN in_patient_count > out_patient_count THEN 'In-patient' ELSE 'Out-patient' END AS majority_group, ROUND(ABS(in_patient_count - out_patient_count) * 100.0 / total_count, 2) AS percentage_deviation FROM (SELECT SUM(CASE WHEN Admission = 'In-patient' THEN 1 ELSE 0 END) AS in_patient_count, SUM(CASE WHEN Admission = 'Out-patient' THEN 1 ELSE 0 END) AS out_patient_count, COUNT(*) AS total_count FROM Patient WHERE SEX = 'Male') AS counts"
}

{
    "sql": "SELECT CASE WHEN in_patient_count > out_patient_count THEN 'In-patient' ELSE 'Outpatient' END AS majority_group, ROUND(ABS(in_patient_count - out_patient_count) * 100.0 / total_count, 2) AS percentage_deviation FROM (SELECT SUM(CASE WHEN Admission = 'In-patient' THEN 1 ELSE 0 END) AS in_patient_count, SUM(CASE WHEN Admission = 'Outpatient' THEN 1 ELSE 0 END) AS out_patient_count, COUNT(*) AS total_count FROM Patient WHERE SEX = 'male') AS counts"
