{
    "sql": "WITH cte_avg_consumption AS (SELECT y.CustomerID, c.Segment, AVG(y.Consumption) AS avg_consumption FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Currency = 'CZK' AND y.Date LIKE '2013-%' GROUP BY y.CustomerID, c.Segment), cte_min_consumers AS (SELECT Segment, MIN(avg_consumption) AS min_avg_consumption FROM cte_avg_consumption GROUP BY Segment) SELECT (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'SME') - (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'LAM') AS diff_SME_LAM, (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'LAM') - (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'KAM') AS diff_LAM_KAM, (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'KAM') - (SELECT min_avg_consumption FROM cte_min_consumers WHERE Segment = 'SME') AS diff_KAM_SME FROM (SELECT 1)"
}

{
    "sql": "WITH cte AS (SELECT c.CustomerID, c.Segment, AVG(ym.Consumption) AS avg_consumption FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'CZK' AND ym.Date LIKE '2013%' GROUP BY c.CustomerID, c.Segment), segment_avg AS (SELECT Segment, AVG(avg_consumption) AS annual_avg FROM cte GROUP BY Segment) SELECT (SELECT annual_avg FROM segment_avg WHERE Segment = 'SME') - (SELECT annual_avg FROM segment_avg WHERE Segment = 'LAM') AS diff_SME_LAM, (SELECT annual_avg FROM segment_avg WHERE Segment = 'LAM') - (SELECT annual_avg FROM segment_avg WHERE Segment = 'KAM') AS diff_LAM_KAM, (SELECT annual_avg FROM segment_avg WHERE Segment = 'KAM') - (SELECT annual_avg FROM segment_avg WHERE Segment = 'SME') AS diff_KAM_SME"
}

{
    "sql": "WITH cte_avg_consumption AS (SELECT c.CustomerID, c.Segment, AVG(ym.Consumption) AS avg_consumption FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'CZK' AND ym.Date LIKE '2013%' GROUP BY c.CustomerID, c.Segment), cte_min_consumption AS (SELECT Segment, MIN(avg_consumption) AS min_avg_consumption FROM cte_avg_consumption GROUP BY Segment) SELECT 'SME-LAM' AS comparison, (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'SME') - (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'LAM') AS difference UNION ALL SELECT 'LAM-KAM', (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'LAM') - (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'KAM') UNION ALL SELECT 'KAM-SME', (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'KAM') - (SELECT min_avg_consumption FROM cte_min_consumption WHERE Segment = 'SME')"
}

{
