{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(ym.Consumption) AS total_consumption, SUBSTR(ym.Date, 1, 4) AS year FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Currency = 'EUR' AND SUBSTR(ym.Date, 1, 4) IN ('2012', '2013') GROUP BY c.Segment, year), segment_yearly AS (SELECT Segment, MAX(CASE WHEN year = '2012' THEN total_consumption END) AS consumption_2012, MAX(CASE WHEN year = '2013' THEN total_consumption END) AS consumption_2013 FROM segment_consumption WHERE Segment IN ('SME', 'LAM', 'KAM') GROUP BY Segment), segment_changes AS (SELECT Segment, (consumption_2013 - consumption_2012) / consumption_2012 * 100 AS percentage_increase FROM segment_yearly WHERE consumption_2012 > 0) SELECT Segment, percentage_increase FROM segment_changes WHERE percentage_increase = (SELECT MAX(percentage_increase) FROM segment_changes) OR percentage_increase = (SELECT MIN(percentage_increase) FROM segment_changes) ORDER BY percentage_increase DESC"
}

{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(ym.Consumption) AS total_consumption, SUBSTR(ym.Date, 1, 4) AS year FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Currency = 'EUR' AND SUBSTR(ym.Date, 1, 4) IN ('2012', '2013') GROUP BY c.Segment, SUBSTR(ym.Date, 1, 4)), segment_yearly AS (SELECT Segment, MAX(CASE WHEN year = '2012' THEN total_consumption END) AS consumption_2012, MAX(CASE WHEN year = '2013' THEN total_consumption END) AS consumption_2013 FROM segment_consumption WHERE Segment IN ('SME', 'LAM', 'KAM') GROUP BY Segment), segment_increase AS (SELECT Segment, (consumption_2013 - consumption_2012) / consumption_2012 * 100 AS pct_increase FROM segment_yearly WHERE consumption_2012 > 0 AND consumption_2013 > 0) SELECT Segment, pct_increase FROM segment_increase WHERE pct_increase = (SELECT MAX(pct_increase) FROM segment_increase) OR pct_increase = (SELECT MIN(pct_increase) FROM segment_increase) ORDER BY pct_increase DESC;"
}

{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(y.Consumption) AS total_consumption, SUBSTR(y.Date, 1, 4) AS year FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Currency = 'EUR' AND (y.Date LIKE '2012%' OR y.Date LIKE '2013%') GROUP BY c.Segment, year), segment_totals AS (SELECT Segment, SUM(CASE WHEN year = '2012' THEN total_consumption ELSE 0 END) AS consumption_2012, SUM(CASE WHEN year = '2013' THEN total_consumption ELSE 0 END) AS consumption_2013 FROM segment_consumption WHERE Segment IN ('SME', 'LAM', 'KAM') GROUP BY Segment), segment_changes AS (SELECT Segment, (consumption_2013 - consumption_2012) / consumption_2012 * 100 AS pct_increase FROM segment_totals WHERE consumption_2012 > 0) SELECT Segment, pct_increase FROM segment_changes WHERE pct_increase = (SELECT MAX(pct_increase) FROM segment_changes) OR pct_increase = (SELECT MIN(pct_increase) FROM segment_changes) ORDER BY pct_increase DESC;"
