{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(CASE WHEN strftime('%Y', t.Date) = '2012' AND c.Currency = 'EUR' THEN t.Amount * t.Price ELSE 0 END) AS consumption_2012, SUM(CASE WHEN strftime('%Y', t.Date) = '2013' AND c.Currency = 'EUR' THEN t.Amount * t.Price ELSE 0 END) AS consumption_2013 FROM customers c JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Segment IN ('SME', 'LAM', 'KAM') AND strftime('%Y', t.Date) IN ('2012', '2013') GROUP BY c.Segment) SELECT Segment, (consumption_2013 - consumption_2012) / NULLIF(consumption_2012, 0) * 100 AS percentage_increase FROM segment_consumption WHERE consumption_2012 > 0 ORDER BY percentage_increase DESC LIMIT 1 UNION ALL SELECT Segment, (consumption_2013 - consumption_2012) / NULLIF(consumption_2012, 0) * 100 AS percentage_increase FROM segment_consumption WHERE consumption_2012 > 0 ORDER BY percentage_increase ASC LIMIT 1"
}

{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(ym.Consumption) AS total_consumption, SUBSTR(ym.Date, 1, 4) AS year FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Currency = 'EUR' AND SUBSTR(ym.Date, 1, 4) IN ('2012', '2013') GROUP BY c.Segment, SUBSTR(ym.Date, 1, 4)), segment_years AS (SELECT Segment, MAX(CASE WHEN year = '2012' THEN total_consumption END) AS consumption_2012, MAX(CASE WHEN year = '2013' THEN total_consumption END) AS consumption_2013 FROM segment_consumption WHERE Segment IN ('SME', 'LAM', 'KAM') GROUP BY Segment), segment_increases AS (SELECT Segment, (consumption_2013 - consumption_2012) / consumption_2012 * 100 AS pct_increase FROM segment_years WHERE consumption_2012 > 0) SELECT 'Biggest Increase' AS metric, Segment, pct_increase FROM segment_increases WHERE pct_increase = (SELECT MAX(pct_increase) FROM segment_increases) UNION ALL SELECT 'Lowest Increase' AS metric, Segment, pct_increase FROM segment_increases WHERE pct_increase = (SELECT MIN(pct_increase) FROM segment_increases)"
